const toast=message=>{const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4300);};
async function api(path,method='GET',data) {
  if(busy&&method!=='GET')return null;
  busy=true;document.body.classList.add('is-busy');
  try {
    const res=await fetch(path,{method,headers:data&&!(data instanceof FormData)?{'Content-Type':'application/json'}:{},body:data?(data instanceof FormData?data:JSON.stringify(data)):undefined});
    const ct=res.headers.get('content-type')||'';
    const payload=ct.includes('json')?await res.json():await res.text();
    if(!res.ok)throw new Error(payload?.error||payload?.errors?.join(' ')||`Request failed (${res.status})`);
    return payload;
  } catch(e){toast(e.message);throw e;}
  finally{busy=false;document.body.classList.remove('is-busy');}
}
function setState(data){if(data?.session){state=data;render();}return data;}
async function action(path,method='POST',data={}){try{return setState(await api(path,method,data));}catch{return null;}}
function go(next){if(next===page){window.scrollTo({top:0,behavior:'smooth'});return;}page=next;location.hash=next;repairPreview=null;render();window.scrollTo({top:0,behavior:'smooth'});}
function health(){if(!campaign())return {label:'No draft yet',class:'unknown'};if(state.launch)return {label:'Simulated launched',class:'good'};if(state.approval&&campaign().status==='APPROVED')return {label:'Approved for simulation',class:'good'};if(!state.inspection)return {label:'Inspection needed',class:'unknown'};
  const c=state.inspection.counts;return c.BLOCKER?{label:`${c.BLOCKER} blocker${c.BLOCKER>1?'s':''}`,class:'bad'}:c.WARNING?{label:`${c.WARNING} warning${c.WARNING>1?'s':''}`,class:'warn'}:{label:'Ready for review',class:'good'};}
function title(eyebrow,heading,description=''){return `<div class="page-head"><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(heading)}</h1><p>${esc(description)}</p></div>`;}
function button(label,act,cls=''){return `<button type="button" class="btn ${cls}" data-action="${esc(act)}">${esc(label)}</button>`;}
function banner(){return `<div class="alert warn"><strong>Demo only</strong>This is a simulated campaign. No ad was published or charged. Merchant inputs are self reported; forecasts and sample performance are illustrative.</div>`;}
function guidePlan(){
  const hi=locale()==='hi',say=(en,hindi)=>hi?hindi:en;
  const pending=Object.values(state.profile).some(v=>['extracted_unconfirmed','imported_unconfirmed'].includes(v.source));
  const hasFacts=['name','type','offer','objective'].some(k=>profile(k)!==null);
  const findings=state.inspection?.counts||{};
  if(state.launch)return {number:6,title:say('Demo complete','डेमो पूरा हुआ'),detail:say('The launch is saved as a simulation. Explore outcomes or try another setting.','लॉन्च सिम्युलेशन के रूप में सहेजा गया है। परिणाम या अन्य सेटिंग देखें।'),target:'learn',action:say('See learning','परिणाम देखें')};
  if(state.approval)return {number:6,title:say('Simulate the launch','लॉन्च सिम्युलेट करें'),detail:say('Approval is recorded. Open Launch to create the demo record; no real ad is published.','मंज़ूरी दर्ज है। डेमो रिकॉर्ड बनाने के लिए लॉन्च खोलें; वास्तविक विज्ञापन नहीं चलेगा।'),target:'launch',action:say('Open launch','लॉन्च खोलें')};
  if(state.inspection&&(findings.BLOCKER||findings.WARNING))return {number:5,title:say('Resolve the findings','निष्कर्ष सुधारें'),detail:say('Compare repair options or acknowledge a warning before review. You can still edit the draft.','समीक्षा से पहले सुधार विकल्प देखें या चेतावनी स्वीकारें। मसौदा भी बदल सकते हैं।'),target:'repair',action:say('Open repairs','सुधार देखें')};
  if(state.inspection)return {number:5,title:say('Review your campaign','अभियान की समीक्षा करें'),detail:say('Check the spend cap, targeting and creative, then approve only if you are satisfied.','खर्च सीमा, लक्ष्य और विज्ञापन सामग्री जाँचें; संतुष्ट होने पर मंज़ूरी दें।'),target:'review',action:say('Open review','समीक्षा खोलें')};
  if(campaign())return {number:4,title:say('Run the inspector','जाँच चलाएँ'),detail:say('Review or edit the draft, save changes, then run checks before approval.','मसौदा देखें या बदलें, सहेजें और मंज़ूरी से पहले जाँच चलाएँ।'),target:'inspect',action:say('Open inspector','जाँच खोलें')};
  if(pending)return {number:2,title:say('Confirm suggested facts','सुझाए तथ्य पुष्ट करें'),detail:say('AI suggestions are waiting for your review. Confirm or reject them, then fill any gaps in Business DNA.','AI सुझाव जाँच की प्रतीक्षा में हैं। इन्हें पुष्ट या अस्वीकार करें, फिर व्यवसाय जानकारी भरें।'),target:'chat',action:say('Review suggestions','सुझाव देखें')};
  if(hasFacts)return {number:3,title:say('Finish Business DNA','व्यवसाय जानकारी पूरी करें'),detail:say('Check your offer, budget and service area. Save the facts, then generate an editable draft.','ऑफ़र, बजट और सेवा क्षेत्र जाँचें। तथ्य सहेजकर बदलने योग्य मसौदा बनाएँ।'),target:'business',action:say('Open Business DNA','व्यवसाय जानकारी खोलें')};
  return {number:1,title:say('Start with your business','अपने व्यवसाय से शुरू करें'),detail:say('Describe it in chat or choose an editable example. You can change settings at any time.','बातचीत में बताएँ या बदलने योग्य उदाहरण चुनें। सेटिंग कभी भी बदल सकते हैं।'),target:'chat',action:page==='chat'?say('Write your message','अपना संदेश लिखें'):say('Start chatting','बातचीत शुरू करें')};
}
function renderGuide(){const guide=$('#guide');if(!guide)return;const plan=guidePlan(),hi=locale()==='hi';
  guide.innerHTML=`<button type="button" class="guide-fab" data-guide-toggle aria-expanded="${guideOpen}" aria-controls="guide-panel" aria-label="${hi?'मार्गदर्शिका खोलें या बंद करें':'Open or close action guide'}">✦ ${hi?'मार्गदर्शिका':'Guide'} <span class="guide-step">${plan.number}/6</span></button>
    ${guideOpen?`<div id="guide-panel" class="guide-panel"><div class="guide-panel-head"><div><span class="guide-kicker">${hi?'अगला उपयोगी कदम':'NEXT USEFUL STEP'} · ${plan.number}/6</span><h2>${esc(plan.title)}</h2></div><button type="button" class="guide-close" data-guide-toggle aria-label="${hi?'मार्गदर्शिका बंद करें':'Close guide'}">×</button></div><p>${esc(plan.detail)}</p><div class="guide-progress" role="progressbar" aria-valuenow="${plan.number}" aria-valuemin="0" aria-valuemax="6" aria-label="${hi?'प्रगति':'Progress'}"><span style="width:${plan.number/6*100}%"></span></div><button type="button" class="btn primary block" data-nav="${plan.target}">${esc(plan.action)} →</button><div class="guide-shortcuts"><span>${hi?'अपनी गति से देखें':'Explore freely'}</span><div><button type="button" data-nav="business">${hi?'व्यवसाय':'Business'}</button><button type="button" data-nav="draft">${hi?'मसौदा':'Draft'}</button><button type="button" data-nav="context">${hi?'संदर्भ':'Context'}</button><button type="button" data-nav="scenarios">${hi?'विकल्प':'What-if'}</button></div></div></div>`:''}`;
}
function renderShell(){const h=health();
  const nav=(items,offset=0)=>items.map(([id,en,hi],i)=>`<button class="nav-btn ${page===id?'active':''}" data-nav="${id}"><span class="nav-num">${String(i+offset+1).padStart(2,'0')}</span>${esc(locale()==='hi'?hi:en)}</button>`).join('');
  const moreOpen=toolsExpanded||steps.slice(8).some(x=>x[0]===page);
  $('#sidebar').innerHTML=`<div class="brand">Bolo<b>Ads</b></div><div class="side-label">${locale()==='hi'?'मुख्य रास्ता':'Main path'}</div><div class="nav-list">${nav(steps.slice(0,8))}</div><button type="button" class="side-group-toggle" data-guide-tools aria-expanded="${moreOpen}">${locale()==='hi'?'और टूल देखें':'Explore tools'} <span>${moreOpen?'−':'+'}</span></button>${moreOpen?`<div class="nav-list">${nav(steps.slice(8),8)}</div>`:''}<div class="side-foot">Independent case study prototype<br>No live ad publishing</div>`;
  $('#topbar').innerHTML=`<div class="top-left"><div class="top-title">${esc(profile('name')||'New campaign')}</div><span class="health ${h.class}" aria-label="${t('health')}: ${esc(h.label)}">● ${esc(h.label)}</span></div><div class="top-actions"><span class="save-indicator">● ${t('save')}</span><select id="language" class="small-select" aria-label="Language"><option value="en" ${locale()==='en'?'selected':''}>English</option><option value="hi" ${locale()==='hi'?'selected':''}>हिन्दी</option></select>${button('Help','help','small ghost')}</div>`;
  const idx=steps.findIndex(x=>x[0]===page),previous=steps[Math.max(0,idx-1)]?.[0],next=steps[Math.min(steps.length-1,idx+1)]?.[0];
  const options=items=>items.map(([id,en,hi])=>`<option value="${id}" ${page===id?'selected':''}>${esc(locale()==='hi'?hi:en)}</option>`).join('');
  $('#mobile-nav').innerHTML=`<button class="btn small" data-nav="${previous}">${t('back')}</button><select class="small-select" id="mobile-step" aria-label="Step"><optgroup label="${locale()==='hi'?'मुख्य रास्ता':'Main path'}">${options(steps.slice(0,8))}</optgroup><optgroup label="${locale()==='hi'?'अन्य टूल':'Explore tools'}">${options(steps.slice(8))}</optgroup></select><button class="btn primary small" data-nav="${next}">${t('continue')}</button>`;
  $('#context').innerHTML=`<div class="context-card"><h3>Business facts</h3>${[['Business',profile('name')],['Offer',profile('offer')],['Service area',profile('serviceRegions')],['Total cap',campaign()?.budgetTotal===undefined?'Unknown':money(campaign()?.budgetTotal)],['Status',campaign()?.status||'NEW']].map(([k,v])=>`<div class="fact-row"><span>${k}</span><b>${esc(fmt(v))}</b></div>`).join('')}</div><div class="context-card"><h3>Current inspection</h3>${state.inspection?`<div class="summary-strip">${Object.entries(state.inspection.counts).map(([k,v])=>`<span class="status ${k}">${v} ${k}</span>`).join('')}</div><div class="small muted">Checked ${new Date(state.inspection.checkedAt).toLocaleString()}</div>`:'<div class="small muted">Run inspection after drafting. Edits make previous results stale.</div>'}</div><div class="context-card"><h3>Trust labels</h3><div class="feature-row"><span class="source confirmed">Merchant confirmed</span></div><div class="feature-row"><span class="source ai">AI suggested</span></div><div class="feature-row"><span class="source simulated">Simulated</span></div></div>`;
}
function startScreen(){const seeds=[['kirana','🛒','Rajesh · Kirana','Local weekend offer and break-even'],['boutique','✦','Priya · Boutique','Jaipur leads and service geography'],['manufacturer','▦','Gujarat manufacturer','National targeting and MOQ'],['stock','◫','Arjun · Catalog','Unavailable SKU and order tracking']];
  return `<div class="card hero"><div class="eyebrow">Business-aware advertising</div><h1>Make ads harder to get wrong.</h1><p>Describe your business, inspect a draft against what you can actually deliver, and choose how to repair risks before a simulated launch.</p><div class="hero-actions">${button('Describe your business','new','primary')}${button('Resume campaign','resume','')}</div></div><div class="page-head"><div class="eyebrow">Try an example</div><h1 style="font-size:24px">See the inspector in action</h1><p>Each example is editable and runs through the same rule engine.</p></div><div class="grid-2">${seeds.map(([id,icon,label,sub])=>`<button class="seed-card" data-seed="${id}"><span class="seed-icon">${icon}</span><strong>${label}</strong><span>${sub}</span></button>`).join('')}</div><div class="card mt-2"><div class="grid-3"><div class="feature-row"><span class="feature-icon">01</span><div><strong>Capture facts</strong><small>Confirm the details that shape a campaign.</small></div></div><div class="feature-row"><span class="feature-icon">02</span><div><strong>Find conflicts</strong><small>See evidence and unknowns before approval.</small></div></div><div class="feature-row"><span class="feature-icon">03</span><div><strong>Repair and learn</strong><small>Compare options and track decisions.</small></div></div></div></div>${banner()}`;}
function chatScreen(){const chat=state.chat||[];const pending=Object.entries(state.profile).filter(([,v])=>v.source==='extracted_unconfirmed');
  return `${title('01 / Conversation','Tell us about your business','Write naturally in English, Hindi or Hinglish. Review and confirm any details suggested from your message.')}
    <div class="card"><div class="card-header"><h2 class="section-title">Conversation</h2><span class="source ${state.capabilities.ai?'ai':''}">${state.capabilities.ai?'Live AI ready':'AI unavailable — manual entry available'}</span></div>
      <div class="chat-log" id="chat-log">${chat.length?chat.map(m=>`<div class="bubble ${m.role}">${esc(m.content)}<small>${esc(m.language||'')} · ${new Date(m.createdAt).toLocaleTimeString()} ${m.role==='assistant'?`<button class="btn small ghost" data-speak="${esc(m.id)}" aria-label="Listen to reply">▶ Listen</button>`:''}</small></div>`).join(''):'<div class="empty">Start with your business, offer and approximate budget. For example: “Meri kirana dukaan Aliganj mein hai; weekend ₹2,000 ka ad chahiye.”</div>'}</div>
      <form id="chat-form" class="chat-composer"><textarea name="userText" aria-label="Message" placeholder="Describe your business or campaign…" required>${esc(transcript)}</textarea><button class="btn primary" ${state.capabilities.ai?'':'disabled title="Configure GROQ_API_KEY on the server"'}>Send</button></form>
      <div class="voice-controls"><button type="button" class="btn small ${recorder?'recording':''}" data-action="${recorder?'stop-record':'record'}" ${state.capabilities.voice?'':'disabled title="Configure GROQ_API_KEY on the server"'}>${recorder?'■ Stop recording':'● Record voice'}</button><span class="audio-state">${esc(voiceError|| (recorder?'Recording · maximum 60 seconds':'Transcript appears here for editing before use. Audio is not retained after transcription.'))}</span></div>
      ${transcript?`<div class="alert">Review and edit the transcript in the message box, then send it. ${button('Clear transcript','clear-transcript','small')}</div>`:''}
      <div class="actions">${button('Enter details manually','business','ghost')}${button('Import website text','import-url','ghost')}</div>
    </div>
    ${pending.length?`<div class="card" id="confirm-facts"><h2 class="section-title">Confirm extracted facts</h2><p class="muted small">AI suggestions are not treated as verified facts until you confirm them.</p>${pending.map(([k,v])=>`<div class="feature-row"><div><strong>${esc(keyName(k))}: ${esc(fmt(v.value))}</strong><small>AI extracted · review before using</small></div><div class="actions"><button class="btn small" data-confirm="${esc(k)}">Confirm</button><button class="btn small ghost" data-reject="${esc(k)}">Reject</button></div></div>`).join('')}</div>`:''}
    <div class="card"><h2 class="section-title">Optional website import</h2><p class="small muted">Public HTML only. Imported text stays unconfirmed.</p><form id="url-form" class="field-grid"><div class="field full"><label for="website-url">Website URL</label><input id="website-url" name="url" type="url" placeholder="https://example.com" required></div><div class="form-actions"> <button class="btn">Inspect website</button></div></form>${importResult?`<div class="alert"><strong>${esc(importResult.title||'Website found')}</strong>${esc(importResult.description||importResult.excerpt)}<div class="actions">${button('Use title as business name','use-import-title','small')}</div></div>`:''}</div>`;}
const fieldInput=(k,type='text',opts={})=>{const v=profile(k),inputId=`p-${k}`;let control;
  if(type==='select') control=`<select id="${inputId}" name="${k}"><option value="">Unknown / skip</option>${opts.options.map(([val,label])=>`<option value="${esc(val)}" ${String(v)===String(val)?'selected':''}>${esc(label)}</option>`).join('')}</select>`;
  else if(type==='textarea')control=`<textarea id="${inputId}" name="${k}">${esc(v??'')}</textarea>`;
  else control=`<input id="${inputId}" name="${k}" type="${type}" ${type==='number'?'min="0" step="0.01"':''} value="${esc(type==='date'&&v?String(v).slice(0,10):Array.isArray(v)?v.join(', '):v??'')}" placeholder="${esc(opts.placeholder||'Optional')}">`;
  return `<div class="field ${opts.full?'full':''}"><label for="${inputId}">${esc(keyName(k))}</label>${control}<div>${sourceBadge(k)}</div>${opts.hint?`<small>${esc(opts.hint)}</small>`:''}</div>`;};
function businessScreen(){return `${title('02 / Business DNA','What is true for your business?','These saved facts guide drafting and inspection. Unknown values stay unknown, and edits invalidate old checks.')}
  <form id="profile-form"><div class="card"><h2 class="section-title">Basics</h2><div class="field-grid">${fieldInput('name')}${fieldInput('type')}${fieldInput('city')}${fieldInput('state')}${fieldInput('website','url',{full:true})}</div></div>
  <div class="card"><h2 class="section-title">Offer & economics</h2><div class="field-grid">${fieldInput('offer','textarea',{full:true})}${fieldInput('objective','select',{options:[['store_visits','Store visits'],['qualified_leads','Qualified leads'],['orders','Orders'],['messages','Messages']]})}${fieldInput('sku')}${fieldInput('price','number')}${fieldInput('contributionBeforeDiscount','number',{hint:'Before discount and before ad cost. Do not include the discount twice.'})}${fieldInput('discount','number')}${fieldInput('extraFulfilmentCost','number',{hint:'Only costs not already included in contribution.'})}${fieldInput('contributionBasisConfirmed','select',{options:[['true','Yes, contribution is before discount'],['false','No / unsure']]})}${fieldInput('acceptableOrders','number')}${fieldInput('minimumOrder')}</div></div>
  <div class="card"><h2 class="section-title">Reach & operations</h2><div class="field-grid">${fieldInput('campaignRegions','text',{hint:'Comma-separated places you want to target.'})}${fieldInput('serviceRegions','text',{hint:'Comma-separated places you can serve. Use India only if confirmed.'})}${fieldInput('budgetTotal','number')}${fieldInput('budgetDaily','number')}${fieldInput('startDate','date')}${fieldInput('endDate','date')}${fieldInput('availability','select',{options:[['available','Available'],['unavailable','Unavailable'],['unknown','Unknown']]})}${fieldInput('responseHours','text',{placeholder:'09:00-18:00'})}${fieldInput('leadSla')}${fieldInput('conversionGoal','select',{options:[['redemptions','Redemptions'],['qualified_leads','Qualified leads'],['orders','Orders'],['store_visits','Store visits']]})}${fieldInput('orderTracking','select',{options:[['manual_redemption','Manual redemption ledger'],['manual_leads','Manual lead ledger'],['manual_orders','Manual order ledger'],['clicks_only','Clicks only']]})}</div><div class="form-actions"><button class="btn primary">${t('saveChanges')}</button>${button('Generate campaign draft','generate-draft','')}</div></div></form>`;}
const draftInput=(k,label,type='text',valueOverride)=>{const v=valueOverride===undefined?campaign()?.[k]:valueOverride;return `<div class="field"><label for="c-${k}">${esc(label)}</label><input id="c-${k}" name="${k}" type="${type}" ${type==='number'?'min="0" step="0.01"':''} value="${esc(Array.isArray(v)?v.join(', '):v??'')}"></div>`;};
function financeCard(f=state.finance,preview=false){return `<div class="card" id="finance-card"><div class="card-header"><h2 class="section-title">Financial lab</h2><span class="source ${f?.state==='CALCULATED'?'confirmed':''}">${preview?'Unsaved preview · ':''}${f?.state==='CALCULATED'?t('calculated'):t('unknown')}</span></div>${f?.state==='CALCULATED'?`<div class="grid-3"><div class="metric"><span class="metric-label">Before offer</span><b>${money(f.contribution)}</b><small>per qualifying order</small></div><div class="metric"><span class="metric-label">After offer</span><b>${money(f.post)}</b><small>before ad cost</small></div><div class="metric"><span class="metric-label">Break-even orders</span><b>${f.breakEven??'Not finite'}</b><small>incremental qualifying orders</small></div></div><p class="small muted">${esc(f.formula)} ${money(f.contribution)} − ${money(f.discount)} − ${money(f.extra)} = ${money(f.post)}. ${f.post>0&&f.budget!==null?`ceil(${money(f.budget)} ÷ ${money(f.post)}) = ${f.breakEven}.`:''} This is not a conversion forecast.</p>`:`<div class="alert warn">${esc(f?.reason||'Confirm contribution and discount to calculate break-even.')}</div>`}</div>`;}
function draftScreen(){const c=campaign();return `${title('03 / Campaign draft','Shape the campaign','Review every suggestion. Changes are saved as a new version and require a fresh inspection.')}
  ${!c?`<div class="card"><p>No draft yet. Save Business DNA, then generate a draft.</p>${button('Generate from business facts','generate-draft','primary')}</div>`:
  `<div class="tabs"><button class="tab ${activeDraftTab==='basic'?'active':''}" data-draft-tab="basic">Basic</button><button class="tab ${activeDraftTab==='advanced'?'active':''}" data-draft-tab="advanced">Advanced</button><button class="tab ${activeDraftTab==='creative'?'active':''}" data-draft-tab="creative">Creative</button></div>
   ${activeDraftTab==='creative'?creativeEditor():`<form id="draft-form"><div class="card"><div class="card-header"><h2 class="section-title">Campaign settings</h2><span class="source ${c.source==='AI suggested'?'ai':''}">${esc(c.source||'Suggested')} · editable</span></div><div class="field-grid">
    ${draftInput('goal','Goal')}${draftInput('offer','Offer')}${draftInput('targetRegions','Target regions · comma-separated')}${draftInput('budgetTotal','Total spend cap · INR','number')}${draftInput('budgetDaily','Daily spend cap · INR','number')}${draftInput('startDate','Start date','date')}${draftInput('endDate','End date','date')}${draftInput('scheduleHours','Scheduled hours · HH:MM-HH:MM or all_day')}${draftInput('discount','Discount · INR','number')}${draftInput('cta','Call to action')}${draftInput('destination','Destination')}</div>
    ${activeDraftTab==='advanced'?`<h3 class="section-subtitle mt-2">Advanced controls</h3><div class="field-grid">${draftInput('excludedRegions','Excluded regions · comma-separated')}${draftInput('offerSku','Offer SKU')}${draftInput('minimumOrderText','Minimum order qualification')}${draftInput('audienceNote','Audience / handling note')}${draftInput('productPriority','Product priority')}${draftInput('format','Ad format')}</div>`:''}<div class="form-actions"><button class="btn primary">${t('saveChanges')}</button>${button('Regenerate from profile','generate-draft','')}</div></div></form>`}
   ${financeCard()}<div class="card"><h2 class="section-title">Test budget checkpoint</h2><p class="small muted">Total and daily caps are planning limits in this simulated experience. No real platform enforces them.</p><div class="grid-3"><div class="metric"><span class="metric-label">Total cap</span><b>${money(c.budgetTotal)}</b></div><div class="metric"><span class="metric-label">Daily cap</span><b>${money(c.budgetDaily)}</b></div><div class="metric"><span class="metric-label">Review checkpoint</span><b>${esc(c.startDate||'Unknown')}</b><small>Review performance before any future scale decision</small></div></div></div><div class="actions">${button(t('inspect'),'inspect-now','primary')}${button('Explore contexts','context','')}${button('Compare what-if scenarios','scenarios','')}</div>`}`;}
function creativeEditor(){const c=campaign();return `<div class="card"><div class="card-header"><h2 class="section-title">Creative variants</h2><span class="source">Illustrative preview · no policy approval</span></div><p class="muted small">Edit at least two variants, approve each, then rerun inspection. A simple claim check flags possible risks.</p><form id="creative-form">${(c.creatives||[]).map((x,i)=>`<div class="split mb-2"><div class="field-grid"><input type="hidden" name="id-${i}" value="${esc(x.id)}"><div class="field full"><label>Variant ${i+1} headline</label><input name="headline-${i}" maxlength="60" value="${esc(x.headline)}"></div><div class="field full"><label>Description</label><textarea name="description-${i}" maxlength="150">${esc(x.description)}</textarea></div><div class="field"><label>Language</label><select name="language-${i}"><option value="en" ${x.language==='en'?'selected':''}>English</option><option value="hi" ${x.language==='hi'?'selected':''}>Hindi</option></select></div><div class="field"><label><input type="checkbox" name="approved-${i}" ${x.approved?'checked':''}> Merchant approves variant</label></div></div><div class="ad-preview">${state.media?`<img class="preview-photo" src="${state.media}" alt="Uploaded product media">`:''}<span class="ad-tag">Ad</span><small>Generic text preview</small><h3>${esc(x.headline)}</h3><p>${esc(x.description)}</p><button type="button" class="btn small">${esc(c.cta||'Learn more')}</button></div></div>`).join('')}<button class="btn primary">Save creative variants</button></form></div><div class="card"><h2 class="section-title">Product image</h2><p class="small muted">Optional PNG, JPEG or WebP under 2 MB. Used only in this preview.</p><input id="media-file" type="file" accept="image/png,image/jpeg,image/webp"><div class="actions">${button('Upload preview image','upload-media','small')}</div></div>`;}
function counts(c){return `<div class="summary-strip">${['BLOCKER','WARNING','SUGGESTION','UNKNOWN','PASS'].map(k=>`<span class="count"><span class="status ${k}">${k}</span><b>${c?.[k]||0}</b></span>`).join('')}</div>`;}
function inspectScreen(){const ins=state.inspection;return `${title('04 / Pre-flight inspector','Find the conflicts before spending','Deterministic checks compare this draft with merchant-confirmed facts. Unknown evidence stays unknown.')}${banner()}
  <div class="card hero" style="background:#fff"><div class="eyebrow">Campaign contradiction & repair engine</div><h2 class="section-title">${ins?'Inspection of revision '+ins.campaignVersion:'Inspection required'}</h2><p class="muted small">${ins?'Snapshot '+ins.inputHash.slice(0,12)+' · rule version '+ins.ruleVersion:'Run a new check after every business, stock, context or campaign edit.'}</p>${counts(ins?.counts)}${button(ins?'Re-run inspection':t('inspect'),'inspect-now','primary')}</div>
  ${ins?`<div class="card"><div class="card-header"><h2 class="section-title">All findings</h2><span class="small muted">${ins.results.length} checks · passed and unknown included</span></div>${ins.results.map(x=>`<div class="check"><div class="check-top"><div><div class="check-title"><span class="check-id">${x.ruleId}</span>${esc(x.category)}</div><p>${esc(x.message)}</p></div><span class="status ${x.state}">${x.state}</span></div><details class="check-detail"><summary>Why this matters · evidence</summary><dl><dt>Fields</dt><dd>${esc(x.fieldPaths.join(', '))}</dd><dt>Values</dt><dd>${esc(JSON.stringify(x.evidenceValues))}</dd><dt>Formula</dt><dd>${esc(x.formula||'Not applicable')}</dd><dt>Confidence</dt><dd>${esc(x.confidenceNote)}</dd></dl><div class="check-actions">${x.state==='WARNING'||x.state==='BLOCKER'?`<button class="btn small" data-fix="${x.ruleId}">Compare repairs</button>`:''}${x.state==='WARNING'?`<button class="btn small" data-ack="${x.ruleId}" ${state.acknowledgments?.includes(x.ruleId)?'disabled':''}>${state.acknowledgments?.includes(x.ruleId)?'Acknowledged':'Keep & acknowledge'}</button>`:''}${x.state==='UNKNOWN'?`<button class="btn small" data-nav="business">Answer in Business DNA</button>`:''}</div></details></div>`).join('')}</div>`:'<div class="empty">No inspection yet. The same rules will run for any example or merchant-created draft.</div>'}<div class="actions">${button('Review campaign','review','dark')}</div>`;}
function repairScreen(){const ins=state.inspection;const warnings=ins?.results.filter(x=>['WARNING','BLOCKER'].includes(x.state))||[];const current=warnings.find(x=>x.ruleId===repairRule)||warnings[0];if(current&&!repairRule)repairRule=current.ruleId;
  const choices=current?state.repairChoices?.[current.ruleId]||[]:[];
  return `${title('05 / Repair Studio','Choose how to respond','Every repair shows changed fields and reruns the same inspector. You can keep and acknowledge a non-blocking risk.')}${!current?'<div class="empty">No current warnings or blockers. Return to inspection or review.</div>':`<div class="card"><div class="field"><label for="repair-select">Finding</label><select id="repair-select">${warnings.map(x=>`<option value="${x.ruleId}" ${x.ruleId===current.ruleId?'selected':''}>${x.ruleId} · ${esc(x.message.slice(0,80))}</option>`).join('')}</select></div><div class="alert ${current.state==='BLOCKER'?'danger':'warn'}"><strong>${current.ruleId} · ${current.state}</strong>${esc(current.message)}</div></div><div class="card"><h2 class="section-title">Repair choices</h2>${choices.map(x=>`<div class="option ${repairPreview?.option?.id===x.id?'selected':''}"><h3>${esc(x.label)}</h3><p>${esc(x.explanation)}</p><div class="actions"><button class="btn small" data-preview="${x.id}">Preview effect</button><button class="btn primary small" data-apply="${x.id}">Apply & recheck</button></div></div>`).join('')}${current.state==='WARNING'?`<div class="option"><h3>Keep original with warning</h3><p>This logs a risk acknowledgment. It does not mark the warning fixed.</p><div class="actions"><button class="btn small" data-ack="${current.ruleId}">Keep & acknowledge</button></div></div>`:''}</div>${repairPreview?`<div class="card"><h2 class="section-title">Before / after preview</h2><div class="split"><div class="diff"><strong>Fields changed</strong><pre>${esc(JSON.stringify(repairPreview.diff,null,2))}</pre></div><div class="diff"><strong>Check counts after repair</strong>${counts(repairPreview.after)}</div></div><p class="small muted">Preview uses the same deterministic rules without changing the active campaign.</p></div>`:''}`}`;}
function repairOptions(rule){const c=campaign();const served=profile('serviceRegions')||[];const options={
  GEO_01:[['Narrow to service area','Target only confirmed service regions.',{targetRegions:served}],['Qualify remote orders','Keep reach, add a minimum order statement.',{minimumOrderText:profile('minimumOrder')||'Please confirm order size before quoting.'}]],
  FIN_01:[['Reduce discount','Test a smaller discount; inspect the new contribution.',{discount:Math.max(0,Number(c?.discount||0)-25)}],['Smaller test cap','Limit spend; the per-order risk may remain.',{budgetTotal:Math.max(100,Math.floor(Number(c?.budgetTotal||1000)/2)),budgetDaily:Math.min(Number(c?.budgetDaily||100),Math.max(100,Math.floor(Number(c?.budgetTotal||1000)/2)))}]],
  FIN_02:[['Lower test budget','Reduce break-even orders.',{budgetTotal:Math.max(100,Math.floor(Number(c?.budgetTotal||1000)/2))}],['Reduce discount','Increase contribution per order.',{discount:Math.max(0,Number(c?.discount||0)-25)}]],
  OPS_01:[['Pause this SKU','Remove unavailable SKU from draft.',{offerSku:null}],['Change schedule','Move the campaign later; confirm stock.',{}]],
  OPS_02:[['Match staffed hours','Only run leads while staffed.',{scheduleHours:profile('responseHours')}],['Plan follow-up','Document how after-hours enquiries are handled.',{audienceNote:'After-hours enquiries receive a response next staffed day.'}]],
  TRACK_01:[['Use enquiry goal','Align goal with tracked leads.',{goal:'qualified_leads'}],['Keep order goal','Record verified orders manually.',{audienceNote:'Merchant will record verified orders manually.'}]],
  COPY_01:[['Update copy','Remove mismatched amount.',{}],['Remove discount claim','Use generic wording.',{}]],
  POL_01:[['Use cautious copy','Remove possible unsupported claims.',{}],['Use offer only','Limit wording to confirmed offer.',{}]],
  CFG_01:[['Set a test cap','Fill valid caps and future dates.',{}]]
};return (options[rule]||[]).map((x,i)=>({id:`${rule}_${i}`,label:x[0],explanation:x[1],patch:x[2]}));}
function reviewScreen(){const c=campaign(),ins=state.inspection,gate=state.gate;return `${title('06 / Review & approval','Know what you are approving','This summary uses the current saved revision. Hard blockers and stale checks prevent approval.')}${banner()}${!c?'<div class="empty">Create a campaign draft first.</div>':`<div class="card"><div class="card-header"><h2 class="section-title">Merchant summary</h2><span class="source">Revision ${version()}</span></div><div class="grid-2">${[['Business',profile('name')],['Offer',c.offer],['Reach',c.targetRegions],['Total cap',money(c.budgetTotal)],['Daily cap',money(c.budgetDaily)],['Dates',`${c.startDate||'?'} → ${c.endDate||'?'}`],['Scheduled hours',c.scheduleHours],['Goal',c.goal],['CTA',c.cta],['Destination',c.destination],['Context include',c.includedTopics],['Context exclude',c.excludedTopics]].map(([k,v])=>`<div class="fact-row"><span>${k}</span><b>${esc(fmt(v))}</b></div>`).join('')}</div></div><div class="card"><h2 class="section-title">Current findings</h2>${ins?`${counts(ins.counts)}<p class="small muted">Warnings require separate acknowledgment. Suggestions are optional.</p>${ins.results.filter(x=>x.state==='WARNING').map(x=>`<div class="feature-row"><div><strong>${x.ruleId} · ${esc(x.message)}</strong><small>${state.acknowledgments?.includes(x.ruleId)?'Risk acknowledged':'Needs acknowledgment'}</small></div><button class="btn small" data-ack="${x.ruleId}" ${state.acknowledgments?.includes(x.ruleId)?'disabled':''}>${state.acknowledgments?.includes(x.ruleId)?'Acknowledged':'Acknowledge'}</button></div>`).join('')}`:'<div class="alert danger">Inspection is stale or missing. Run it before approval.</div>'}</div><div class="card"><h2 class="section-title">Human approval</h2><div class="alert ${gate.ok?'success':'danger'}">${esc(gate.reason)}</div><label class="field"><span><input id="consent" type="checkbox"> I understand this is a simulated launch. No ad will be published or charged.</span></label><div class="actions"><button class="btn primary" data-action="approve" ${gate.ok?'':'disabled'}>${t('approve')}</button>${button('View advanced history','history','')}${button(t('inspect'),'inspect-now','')}</div></div>`}`;}
function launchScreen(){const launch=state.launch;return `${title('07 / Simulated launch','Ready for the demonstration','No ad network is connected. The launch record is saved in your private browser session.')}${banner()}${launch?`<div class="card"><div class="alert success"><strong>Simulated launch saved</strong>${esc(launch.notice)}</div><div class="grid-3"><div class="metric"><span class="metric-label">Demo reference</span><b style="font-size:18px">${esc(launch.id)}</b></div><div class="metric"><span class="metric-label">Real spend</span><b>₹0</b><small>No charge or publishing</small></div><div class="metric"><span class="metric-label">Saved at</span><b style="font-size:16px">${new Date(launch.at).toLocaleString()}</b></div></div><div class="actions">${button('See learning example','learn','primary')}${button('View audit history','history','')}${button('Duplicate for editing','duplicate','')}</div></div>`:`<div class="card"><p>${state.approval?'Approved revision is ready for a simulated provider action.':'Review and approve the current revision first.'}</p><button class="btn primary" data-action="simulate" ${state.approval?'':'disabled'}>${t('launch')}</button></div>`}`;}
function learnScreen(){const outcomes=state.outcomes||[],demo=state.demo,fixture=state.report?.simulatedPerformance;const counts=kind=>outcomes.filter(x=>x.kind===kind).length;
  return `${title('08 / Learn','Clicks are not customers','Sample platform metrics and merchant-recorded outcomes have separate sources. Nothing here is live ad data.')}${banner()}<div class="tabs"><button class="tab ${learnView==='simulated'?'active':''}" data-learn-tab="simulated">Simulated performance example</button><button class="tab ${learnView==='merchant'?'active':''}" data-learn-tab="merchant">Merchant recorded outcomes</button></div>
  ${learnView==='simulated'?(fixture?`<div class="card"><div class="card-header"><h2 class="section-title">Illustrative sample · ${esc(demo)}</h2><span class="source simulated">Simulated</span></div><div class="grid-3">${[['Impressions',fixture.impressions],['Clicks',fixture.clicks],['Message starts','Untracked'],['Qualified leads','Unknown'],['Verified orders','Unknown'],['Sample spend',money(fixture.spend)]].map(([k,v])=>`<div class="metric"><span class="metric-label">${k}</span><b>${esc(v)}</b></div>`).join('')}</div><div class="alert warn">${fixture.clicks} clicks are shown in this simulated example; message starts were not verified. These numbers are illustrative, not observed campaign results.</div></div>`:'<div class="empty">Load a named example to see clearly labelled simulated performance. Merchant outcomes remain available below.</div>'):
  `<div class="card"><div class="card-header"><h2 class="section-title">Verified by the merchant</h2><span class="source confirmed">Merchant recorded</span></div><div class="grid-3">${[['Qualified leads',counts('qualified_lead')],['Redemptions',counts('redemption')],['Orders',counts('order')]].map(([k,v])=>`<div class="metric"><span class="metric-label">${k}</span><b>${v}</b></div>`).join('')}</div><div class="table-wrap mt-2"><table class="table"><thead><tr><th>Date</th><th>Kind</th><th>Amount</th><th>Notes</th></tr></thead><tbody>${outcomes.map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.kind)}</td><td>${esc(x.amount===null?'Unknown':money(x.amount))}</td><td>${esc(x.notes)}</td></tr>`).join('')||'<tr><td colspan="4">No merchant outcomes recorded yet.</td></tr>'}</tbody></table></div></div>`}
  <div class="card"><h2 class="section-title">Record a real business outcome</h2><p class="small muted">This is a merchant record. It does not prove which ad caused the action.</p><form id="outcome-form" class="field-grid"><div class="field"><label>Outcome kind</label><select name="kind"><option value="qualified_lead">Qualified enquiry</option><option value="redemption">Offer redemption</option><option value="order">Verified order</option><option value="message_start">Message start</option></select></div><div class="field"><label>Date</label><input type="date" name="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Value (INR, optional)</label><input type="number" min="0" step="0.01" name="amount"></div><div class="field"><label>Notes</label><input name="notes" maxlength="500"></div><div class="form-actions"><button class="btn primary">Record outcome</button></div></form></div>`;}
function contextScreen(){const c=campaign();return `${title('Contextual placement explorer','Choose illustrative content topics','These are example categories, not actual publisher inventory or audience reach.')}${!c?'<div class="empty">Create a campaign draft first.</div>':`<div class="card"><h2 class="section-title">Topics</h2><div class="topic-grid">${state.topics.map(topic=>{const inc=c.includedTopics.includes(topic),exc=c.excludedTopics.includes(topic);return `<div class="topic"><strong>${esc(topic)}</strong><span class="source ${inc?'confirmed':exc?'simulated':''}">${inc?'Included':exc?'Excluded':'Unselected'}</span><div class="actions"><button class="btn small" data-topic="${esc(topic)}" data-topic-mode="include">Include</button><button class="btn small" data-topic="${esc(topic)}" data-topic-mode="exclude">Exclude</button><button class="btn small ghost" data-topic="${esc(topic)}" data-topic-mode="clear">Clear</button></div></div>`;}).join('')}</div></div><div class="card"><h2 class="section-title">Example page context</h2><div class="ad-preview"><span class="source simulated">Illustrative page mockup</span><h3>${esc(c.includedTopics[0]||'Local shopping')} article</h3><p>A hypothetical content page relevant to this topic. No real URL, placement, inventory or rate is implied.</p><div class="ad-preview"><span class="ad-tag">Ad</span><h3>${esc(c.creatives[0]?.headline||'Your ad')}</h3><p>${esc(c.creatives[0]?.description||'Campaign copy')}</p></div></div></div>`}`;}
function inventoryScreen(){return `${title('Inventory & readiness','Check what you can actually promote','Upload a CSV or edit stock manually. This is a local register, not a live commerce integration.')}
  <div class="card"><h2 class="section-title">Import stock CSV</h2><p class="small muted">Columns: SKU,name,quantity,active,lastUpdated. Upload replaces the local register. Errors identify rows.</p><input type="file" id="inventory-file" accept=".csv,text/csv"><div class="actions">${button('Import CSV','inventory-import','primary')}${button('Load sample feed','inventory-sample','')}</div>${inventoryErrors.length?`<div class="alert danger">${inventoryErrors.map(esc).join('<br>')}</div>`:''}</div><div class="card"><h2 class="section-title">Stock register</h2><div class="table-wrap"><table class="table"><thead><tr><th>SKU</th><th>Name</th><th>Quantity</th><th>Active</th><th>Updated</th><th>Action</th></tr></thead><tbody>${state.inventory.map(x=>`<tr><td>${esc(x.sku)}</td><td>${esc(x.name)}</td><td>${x.quantity}</td><td>${x.active?'Yes':'No'}</td><td>${esc(x.lastUpdated)}</td><td><button class="btn small" data-stock="${esc(x.sku)}">Edit</button></td></tr>`).join('')||'<tr><td colspan="6">No stock records yet.</td></tr>'}</tbody></table></div><form id="stock-form" class="field-grid mt-2"><div class="field"><label>SKU</label><input name="sku" required></div><div class="field"><label>Name</label><input name="name"></div><div class="field"><label>Quantity</label><input name="quantity" type="number" min="0" step="1" required></div><div class="field"><label><input type="checkbox" name="active" checked> Active</label></div><div class="form-actions"><button class="btn primary">Save stock</button></div></form></div>`;}
function integrityScreen(){const a=state.conversionAudit;return `${title('Conversion data integrity','See what may be counted twice','Known duplicates are grouped only by a shared normalized transaction ID. Same values without IDs remain separate.')}
  <div class="card"><h2 class="section-title">Upload event CSV</h2><p class="small muted">Columns: transactionId,time,value,source,eventType. Upload one or two sources, such as GA4 and shop orders.</p><form id="events-form" class="field-grid"><div class="field"><label>Source name</label><input name="source" placeholder="GA4" required></div><div class="field"><label>CSV file</label><input name="file" type="file" accept=".csv,text/csv" required></div><div class="form-actions"><button class="btn primary">Audit events</button></div></form>${eventErrors.length?`<div class="alert danger">${eventErrors.map(esc).join('<br>')}</div>`:''}</div><div class="grid-3"><div class="metric"><span class="metric-label">Original events</span><b>${a.originalCount}</b></div><div class="metric"><span class="metric-label">Known unique IDs</span><b>${a.knownUniqueTransactions}</b></div><div class="metric"><span class="metric-label">Uncertain records</span><b>${a.uncertainRecords.length}</b></div></div><div class="card mt-2"><h2 class="section-title">Duplicate candidates</h2>${a.duplicateCandidates.length?a.duplicateCandidates.map(g=>`<div class="feature-row"><div><strong>${esc(g.transactionId)}</strong><small>${g.records.length} source events · ${esc(g.records.map(x=>x.source).join(', '))}</small></div></div>`).join(''):'<div class="empty">No shared transaction IDs found across events.</div>'}<h3 class="section-subtitle mt-2">Uncertain without IDs</h3><p class="small muted">${a.uncertainRecords.length} record(s) remain separate. Amount alone is not enough to merge them.</p>${button('Download audit JSON','export','small')}</div>`;}
function scenariosScreen(){const c=campaign();return `${title('What-if lab','Compare controlled alternatives','Scenarios use your assumptions and the same rules. They do not predict clicks, sales or ROI.')}${!c?'<div class="empty">Create a draft first.</div>':`<div class="card"><h2 class="section-title">Save a scenario</h2><form id="scenario-form" class="field-grid"><div class="field"><label>Scenario name</label><input name="name" placeholder="Smaller local test" required></div><div class="field"><label>Discount (INR)</label><input name="discount" type="number" min="0" step="0.01" value="${esc(c.discount??'')}"></div><div class="field"><label>Total cap (INR)</label><input name="budgetTotal" type="number" min="0" step="0.01" value="${esc(c.budgetTotal??'')}"></div><div class="field"><label>Target areas · comma-separated</label><input name="targetRegions" value="${esc(c.targetRegions.join(', '))}"></div><div class="field"><label>Scheduled hours</label><input name="scheduleHours" value="${esc(c.scheduleHours||'')}"></div><div class="form-actions"><button class="btn primary">Calculate scenario</button></div></form></div><div class="card"><h2 class="section-title">Saved comparisons</h2>${state.scenarios.length?state.scenarios.map(s=>`<div class="option"><div class="card-header"><div><h3>${esc(s.name)}</h3><p>Based on revision ${s.baseVersion} · ${esc(s.draft.targetRegions.join(', '))}</p></div><span class="source">Calculated</span></div><div class="grid-3"><div class="metric"><span class="metric-label">Post-offer contribution</span><b>${s.finance.state==='CALCULATED'?money(s.finance.post):'Unknown'}</b></div><div class="metric"><span class="metric-label">Break-even orders</span><b>${s.finance.breakEven??'Unknown'}</b></div><div class="metric"><span class="metric-label">Warnings</span><b>${s.inspection.counts.WARNING}</b></div></div><div class="actions"><button class="btn small" data-scenario="${s.id}">Apply to active draft</button></div></div>`).join(''):'<div class="empty">Save two alternatives to compare them side by side.</div>'}</div><div class="card"><h2 class="section-title">Small experiment plan</h2><p>Choose a maximum test cap, then pause at the saved end date to review merchant-recorded outcomes. These are planning assumptions and require your approval before any active draft changes.</p></div>`}`;}
function scenariosScreenV2(){const c=campaign();if(!c)return `${title('What-if lab','Compare controlled alternatives')}<div class="empty">Create a draft first.</div>`;
  return `${title('What-if lab','Compare controlled alternatives','Scenarios use merchant-entered assumptions and the same checks. They do not predict clicks, sales or ROI.')}
    <div class="card"><h2 class="section-title">Save or update a scenario</h2><form id="scenario-form" class="field-grid">
      <input type="hidden" name="id"><div class="field"><label>Scenario name</label><input name="name" placeholder="Smaller local test" required></div>
      <div class="field"><label>Contribution before discount (INR)</label><input name="contributionBeforeDiscount" type="number" min="0" step="0.01" value="${esc(profile('contributionBeforeDiscount')??'')}"><small>Merchant assumption for this scenario only.</small></div>
      <div class="field"><label>Extra variable cost (INR)</label><input name="extraFulfilmentCost" type="number" min="0" step="0.01" value="${esc(profile('extraFulfilmentCost')??'')}"><small>Enter 0 if there is no extra variable cost.</small></div>
      <div class="field"><label>Discount (INR)</label><input name="discount" type="number" min="0" step="0.01" value="${esc(c.discount??'')}"></div>
      <div class="field"><label>Total test cap (INR)</label><input name="budgetTotal" type="number" min="0" step="0.01" value="${esc(c.budgetTotal??'')}"></div>
      <div class="field"><label>Target areas · comma-separated</label><input name="targetRegions" value="${esc(c.targetRegions.join(', '))}"></div>
      <div class="field"><label>Scheduled hours</label><input name="scheduleHours" value="${esc(c.scheduleHours||'')}"></div>
      <div class="form-actions"><button class="btn primary">Calculate scenario</button></div></form></div>
    <div class="card"><h2 class="section-title">Saved comparisons</h2>${state.scenarios.length?state.scenarios.map(s=>`<div class="option"><div class="card-header"><div><h3>${esc(s.name)}</h3><p>Based on revision ${s.baseVersion} · ${esc(s.draft.targetRegions.join(', '))}</p></div><span class="source">Calculated</span></div><div class="grid-3"><div class="metric"><span class="metric-label">Post-offer contribution</span><b>${s.finance.state==='CALCULATED'?money(s.finance.post):'Unknown'}</b></div><div class="metric"><span class="metric-label">Break-even orders</span><b>${s.finance.breakEven??'Unknown'}</b></div><div class="metric"><span class="metric-label">Warnings</span><b>${s.inspection.counts.WARNING}</b></div></div><div class="actions"><button class="btn small" data-scenario-edit="${s.id}">Edit scenario</button><button class="btn small" data-scenario="${s.id}">Apply to active draft</button></div></div>`).join(''):'<div class="empty">Save two alternatives to compare them side by side.</div>'}</div>
    <div class="card"><h2 class="section-title">Small experiment plan</h2><p>Use the total test cap and saved end date as a review checkpoint. Only merchant-recorded outcomes should inform a later scale decision.</p></div>`;
}
function providerScreen(){const p=state.providerPreview;return `${title('Provider preview','See how this draft would map','A generic simulated adapter validates and previews fields. There is no real ad network publishing or charging.')}${banner()}${p?`<div class="card"><div class="card-header"><h2 class="section-title">Normalized payload</h2><span class="source simulated">Simulation only</span></div><div class="diff"><pre>${esc(JSON.stringify(p.payload,null,2))}</pre></div><h3 class="section-subtitle mt-2">Unsupported mappings</h3><ul>${p.unsupportedMappings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="actions">${button('Review for simulated approval','review','primary')}</div></div>`:'<div class="empty">Create a draft to preview the provider payload.</div>'}`;}
function historyScreen(){const events=[...(state.audit||[])].reverse();return `${title('History & export','Every decision stays visible','Suggested, applied, acknowledged and reverted actions are recorded separately.')}
  <div class="card"><div class="actions" style="margin-top:0">${button('Download campaign JSON','export','primary')}${button('Download readable summary','export-summary','')}${button('Duplicate for editing','duplicate','')}</div><p class="small muted">Exports include latest inspection, acknowledgments, provenance and the simulation notice.</p></div><div class="card"><h2 class="section-title">Change ledger</h2>${events.length?`<div class="timeline">${events.map(x=>`<div class="timeline-item"><strong>${esc(x.type.replaceAll('_',' '))} <span class="source">${esc(x.status)}</span></strong><small>${esc(x.actor)} · ${new Date(x.at).toLocaleString()} · revision ${x.revision}</small>${x.explanation?`<p class="small muted">${esc(x.explanation)}</p>`:''}${x.before||x.after?`<details><summary class="small">See before / after</summary><div class="split mt-2"><div class="diff"><strong>Before</strong><pre>${esc(JSON.stringify(x.before,null,2))}</pre></div><div class="diff"><strong>After</strong><pre>${esc(JSON.stringify(x.after,null,2))}</pre></div></div></details>`:''}${['campaign_edit','repair_applied','profile_edit','scenario_applied'].includes(x.type)?`<button class="btn small mt-2" data-revert="${x.id}">Revert change</button>`:''}</div>`).join('')}</div>`:'<div class="empty">No actions recorded yet.</div>'}</div>`;}
function helpScreen(){return `${title('Help','How BoloAds works','This independent case-study prototype does not claim official Media.net affiliation.')}
  <div class="card"><h2 class="section-title">A short path through the demo</h2><div class="feature-row"><span class="feature-icon">1</span><div><strong>Choose an example or enter facts</strong><small>Example facts are editable; AI-extracted facts require confirmation.</small></div></div><div class="feature-row"><span class="feature-icon">2</span><div><strong>Generate and inspect</strong><small>Rules show blockers, warnings, suggestions, unknowns and passes.</small></div></div><div class="feature-row"><span class="feature-icon">3</span><div><strong>Repair or acknowledge</strong><small>Only blockers prevent approval. Warnings need an explicit acknowledgment.</small></div></div><div class="feature-row"><span class="feature-icon">4</span><div><strong>Approve a simulated launch</strong><small>No real ad is published or charged.</small></div></div></div><div class="card"><h2 class="section-title">Data and voice</h2><p>Voice requires a server-side Groq key and browser microphone permission. You edit the transcript before using it. Audio is not retained after transcription. Browser speech playback is available only when your device has a suitable installed voice.</p><p>Anonymous campaign data is stored on this server, isolated by a private browser session cookie. Avoid entering sensitive personal or payment information in a public demo.</p><div class="actions">${button('Go to start','start','primary')}</div></div>`;}
function localizeDom(){if(locale()!=='hi')return;
  for(const check of document.querySelectorAll('.check')){
    const rule=check.querySelector('.check-id')?.textContent,stateName=check.querySelector('.status')?.textContent;
    const translation=hindiRules[rule]?.[stateName];if(translation){const p=check.querySelector('.check-top p');if(p)p.textContent=translation;}
  }
  const walker=document.createTreeWalker($('#app'),NodeFilter.SHOW_TEXT);let node;
  while(node=walker.nextNode()){
    if(node.parentElement?.closest('pre,code,textarea,script,style'))continue;
    const raw=node.nodeValue.trim(),translation=hindi[raw];
    if(translation)node.nodeValue=node.nodeValue.replace(raw,translation);
  }
}
function render(){if(!state)return;renderShell();const screens={start:startScreen,chat:chatScreen,business:businessScreen,draft:draftScreen,inspect:inspectScreen,repair:repairScreen,review:reviewScreen,launch:launchScreen,learn:learnScreen,context:contextScreen,inventory:inventoryScreen,integrity:integrityScreen,scenarios:scenariosScreenV2,provider:providerScreen,history:historyScreen,help:helpScreen};$('#main').innerHTML=(screens[page]||startScreen)();localizeDom();renderGuide();document.title=`BoloAds · ${steps.find(x=>x[0]===page)?.[1]||'Start'}`;if(page==='chat')$('#chat-log')?.scrollTo(0,99999);}

function formData(form){return new FormData(form);}
const numberOrNull=x=>x===''?null:Number(x);
const arrayOrNull=x=>x.trim()?x.split(',').map(v=>v.trim()).filter(Boolean):null;
async function readFile(file){return file?await file.text():'';}
document.addEventListener('submit',async e=>{const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();const fd=formData(form);
  if(form.id==='chat-form'){const text=String(fd.get('userText')||'').trim();if(!text)return;const result=await action('/api/chat','POST',{userText:text,locale:locale(),transcriptEdited:Boolean(transcript&&text!==transcript.trim())});if(result){transcript='';voiceError='';toast('AI reply saved. Confirm extracted facts before using them.');}}
  if(form.id==='url-form'){try{const result=await api('/api/import-url','POST',{url:fd.get('url')});importResult=result.importResult;setState(result);toast('Website text imported as unconfirmed.');}catch{}}
  if(form.id==='profile-form'){const patch={};for(const [k,v] of fd.entries()){let val=String(v).trim();if(['campaignRegions','serviceRegions'].includes(k))val=arrayOrNull(val);else if(['price','budgetTotal','budgetDaily','contributionBeforeDiscount','discount','extraFulfilmentCost','acceptableOrders'].includes(k))val=numberOrNull(val);else if(k==='contributionBasisConfirmed')val=val===''?null:val==='true';else if(val==='')val=null;patch[k]={value:val,source:val===null?'unknown':'user_confirmed'};}const result=await action('/api/profile','POST',{patch,expectedVersion:version()});if(result)toast('Business facts saved. Run inspection after drafting.');}
  if(form.id==='draft-form'){const patch={};for(const [k,v] of fd.entries()){let val=String(v).trim();if(['targetRegions','excludedRegions'].includes(k))val=arrayOrNull(val)||[];else if(['budgetTotal','budgetDaily','discount'].includes(k))val=numberOrNull(val);else if(val==='')val=null;patch[k]=val;}const result=await action('/api/draft','PATCH',{patch,expectedVersion:version()});if(result)toast('Campaign saved. Inspection is now needed.');}
  if(form.id==='creative-form'){const c=campaign(),creatives=c.creatives.map((x,i)=>({id:x.id,headline:String(fd.get(`headline-${i}`)||''),description:String(fd.get(`description-${i}`)||''),language:String(fd.get(`language-${i}`)||'en'),approved:fd.has(`approved-${i}`)}));const result=await action('/api/draft','PATCH',{patch:{creatives},expectedVersion:version()});if(result)toast('Creative variants saved.');}
  if(form.id==='outcome-form'){const result=await action('/api/outcomes','POST',{kind:fd.get('kind'),date:fd.get('date'),amount:fd.get('amount')===''?null:Number(fd.get('amount')),notes:fd.get('notes')});if(result){learnView='merchant';toast('Merchant outcome recorded.');}}
  if(form.id==='stock-form'){const result=await action('/api/inventory/update','POST',{sku:fd.get('sku'),name:fd.get('name'),quantity:Number(fd.get('quantity')),active:fd.has('active')});if(result)toast('Stock saved and checks rerun.');}
  if(form.id==='events-form'){const file=fd.get('file');if(!file?.size)return toast('Choose a CSV file.');try{const result=await api('/api/events/import','POST',{source:fd.get('source'),csv:await readFile(file)});eventErrors=[];setState(result);toast('Conversion events audited.');}catch(error){eventErrors=[error.message];render();}}
  if(form.id==='scenario-form'){const patch={discount:numberOrNull(fd.get('discount')),budgetTotal:numberOrNull(fd.get('budgetTotal')),targetRegions:arrayOrNull(String(fd.get('targetRegions')||''))||[],scheduleHours:fd.get('scheduleHours')};const assumptions={contributionBeforeDiscount:numberOrNull(fd.get('contributionBeforeDiscount')),extraFulfilmentCost:numberOrNull(fd.get('extraFulfilmentCost'))};const result=await action('/api/scenarios','POST',{id:fd.get('id')||undefined,name:fd.get('name'),patch,assumptions});if(result)toast('Scenario calculated without changing the active draft.');}
});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='language'){await action('/api/session','POST',{locale:el.value});return;}if(el.id==='mobile-step'){go(el.value);return;}if(el.id==='repair-select'){repairRule=el.value;repairPreview=null;render();return;}});
document.addEventListener('input',e=>{const form=e.target.closest?.('#draft-form');if(!form||!['discount','budgetTotal'].includes(e.target.name)||!$('#finance-card'))return;
  const saved=state.finance;let next=saved;
  if(saved?.state==='CALCULATED'){
    const discount=numberOrNull(form.elements.discount.value),budget=numberOrNull(form.elements.budgetTotal.value);
    next=discount===null||discount<0?{state:'UNKNOWN',reason:'Enter a discount to preview the calculation.'}:
      {...saved,discount,budget:budget===null||budget<0?null:budget,post:saved.contribution-discount-saved.extra};
    if(next.state==='CALCULATED')next.breakEven=next.post>0&&next.budget!==null?Math.ceil(next.budget/next.post):null;
  }
  $('#finance-card').outerHTML=financeCard(next,true);localizeDom();
});
document.addEventListener('click',async e=>{const target=e.target.closest('button');if(!target)return;
  if('guideToggle' in target.dataset){guideOpen=!guideOpen;localStorage.setItem('boloads-guide-open',String(guideOpen));renderGuide();return;}
  if('guideTools' in target.dataset){toolsExpanded=!toolsExpanded;renderShell();return;}
  if(target.dataset.nav){if(target.closest('#guide')&&target.dataset.nav==='chat'&&page==='chat'){if(guidePlan().number===2)$('#confirm-facts')?.scrollIntoView({behavior:'smooth'});else $('#chat-form textarea')?.focus();return;}go(target.dataset.nav);return;}
  if(target.dataset.seed){const result=await action('/api/reset','POST',{seed:target.dataset.seed,locale:locale()});if(result){repairRule=null;go('business');toast('Example loaded. All fields can be edited.');}return;}
  if(target.dataset.confirm){const k=target.dataset.confirm;const result=await action('/api/profile','POST',{patch:{[k]:{value:profile(k),source:'user_confirmed'}},expectedVersion:version()});if(result)toast(`${keyName(k)} confirmed.`);return;}
  if(target.dataset.reject){const result=await action('/api/profile/reject','POST',{field:target.dataset.reject,expectedVersion:version()});if(result)toast('Suggestion rejected and logged.');return;}
  if(target.dataset.speak){const message=state.chat.find(x=>x.id===target.dataset.speak);if(!message)return;
    if(!('speechSynthesis' in window)){toast('Audio unavailable on this device.');return;}
    const desired=message.language==='hi'||message.language==='hinglish'?'hi':'en';
    const voice=speechSynthesis.getVoices().find(x=>x.lang.toLowerCase().startsWith(desired));
    if(!voice){toast('Audio unavailable on this device. Read the text reply instead.');return;}
    speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(message.content);utterance.voice=voice;utterance.lang=voice.lang;speechSynthesis.speak(utterance);return;}
  if(target.dataset.draftTab){activeDraftTab=target.dataset.draftTab;render();return;}
  if(target.dataset.learnTab){learnView=target.dataset.learnTab;render();return;}
  if(target.dataset.fix){repairRule=target.dataset.fix;go('repair');return;}
  if(target.dataset.ack){const result=await action('/api/ack','POST',{ruleId:target.dataset.ack,expectedVersion:version()});if(result)toast('Warning acknowledged, not marked fixed.');return;}
  if(target.dataset.preview){const result=await api('/api/repair/preview','POST',{ruleId:repairRule,optionId:target.dataset.preview}).catch(()=>null);if(result){repairPreview=result;render();}return;}
  if(target.dataset.apply){const result=await action('/api/repair/apply','POST',{ruleId:repairRule,optionId:target.dataset.apply,expectedVersion:version()});if(result){repairRule=null;repairPreview=null;toast('Repair applied and inspection rerun.');go('inspect');}return;}
  if(target.dataset.topic){const c=campaign(),topic=target.dataset.topic,mode=target.dataset.topicMode;let inc=[...c.includedTopics],exc=[...c.excludedTopics];inc=inc.filter(x=>x!==topic);exc=exc.filter(x=>x!==topic);if(mode==='include')inc.push(topic);if(mode==='exclude')exc.push(topic);const result=await action('/api/draft','PATCH',{patch:{includedTopics:inc,excludedTopics:exc},expectedVersion:version()});if(result)toast('Context preference saved. Inspection is stale.');return;}
  if(target.dataset.stock){const item=state.inventory.find(x=>x.sku===target.dataset.stock);const f=$('#stock-form');if(item&&f){f.elements.sku.value=item.sku;f.elements.name.value=item.name;f.elements.quantity.value=item.quantity;f.elements.active.checked=item.active;f.scrollIntoView({behavior:'smooth'});}return;}
  if(target.dataset.scenarioEdit){const item=state.scenarios.find(x=>x.id===target.dataset.scenarioEdit),f=$('#scenario-form');if(item&&f){f.elements.id.value=item.id;f.elements.name.value=item.name;f.elements.contributionBeforeDiscount.value=item.assumptions?.contributionBeforeDiscount??'';f.elements.extraFulfilmentCost.value=item.assumptions?.extraFulfilmentCost??'';f.elements.discount.value=item.draft.discount??'';f.elements.budgetTotal.value=item.draft.budgetTotal??'';f.elements.targetRegions.value=item.draft.targetRegions.join(', ');f.elements.scheduleHours.value=item.draft.scheduleHours??'';f.scrollIntoView({behavior:'smooth'});}return;}
  if(target.dataset.scenario){if(!confirm('Replace the active draft with this scenario and rerun inspection?'))return;const result=await action('/api/scenarios/apply','POST',{id:target.dataset.scenario,expectedVersion:version()});if(result){toast('Scenario applied and inspected.');go('inspect');}return;}
  if(target.dataset.revert){if(!confirm('Revert this change and create a new inspected revision?'))return;const result=await action('/api/ledger/revert','POST',{eventId:target.dataset.revert,expectedVersion:version()});if(result)toast('Change reverted and inspected.');return;}
  const a=target.dataset.action;if(!a)return;
  if(steps.some(x=>x[0]===a)){go(a);return;}
  if(a==='new'){const result=await action('/api/reset','POST',{locale:locale()});if(result)go('chat');return;}
  if(a==='resume'){go(campaign()?'draft':'chat');return;}
  if(a==='generate-draft'){const result=await action('/api/draft/generate','POST',{expectedVersion:version()});if(result){toast('Editable draft generated.');go('draft');}return;}
  if(a==='inspect-now'){const result=await action('/api/inspect','POST',{expectedVersion:version()});if(result){toast('Inspection completed.');go('inspect');}return;}
  if(a==='approve'){if(!$('#consent')?.checked)return toast('Confirm the simulated launch notice first.');const result=await action('/api/approve','POST',{consent:true,expectedVersion:version()});if(result){toast('Current revision approved for simulation.');go('launch');}return;}
  if(a==='simulate'){const result=await action('/api/simulate-launch','POST',{});if(result)toast('Simulated launch saved. No ad was published or charged.');return;}
  if(a==='duplicate'){const result=await action('/api/draft/generate','POST',{expectedVersion:version()});if(result){toast('New editable draft created from business facts.');go('draft');}return;}
  if(a==='export'||a==='export-summary'){const url=a==='export'?(page==='integrity'?'/api/conversions/report':'/api/export'):'/api/export?format=summary';const link=document.createElement('a');link.href=url;link.download=a==='export'?(page==='integrity'?'boloads-conversion-audit.json':'boloads-campaign.json'):'boloads-summary.txt';document.body.append(link);link.click();link.remove();toast('Export downloaded.');return;}
  if(a==='clear-transcript'){transcript='';render();return;}
  if(a==='record'){await startRecording();return;}
  if(a==='stop-record'){stopRecording();return;}
  if(a==='import-url'){go('chat');setTimeout(()=>$('#website-url')?.focus(),50);return;}
  if(a==='use-import-title'){if(!importResult?.title)return;const result=await action('/api/profile','POST',{patch:{name:{value:importResult.title,source:'imported_unconfirmed'},website:{value:importResult.url,source:'imported_unconfirmed'}},expectedVersion:version()});if(result)toast('Imported fields need merchant confirmation.');return;}
  if(a==='inventory-import'){const file=$('#inventory-file')?.files?.[0];if(!file)return toast('Choose a CSV file.');const csv=await readFile(file);try{const result=await api('/api/inventory/import','POST',{csv});inventoryErrors=[];setState(result);toast('Inventory updated and checks rerun.');}catch(error){inventoryErrors=[error.message];render();}return;}
  if(a==='inventory-sample'){const csv='SKU,name,quantity,active,lastUpdated\nORG-01,Storage organizer,0,true,2026-11-12\nORG-02,Desk shelf,18,true,2026-11-12';const result=await action('/api/inventory/import','POST',{csv});if(result)toast('Sample feed loaded; it is not a live integration.');return;}
  if(a==='upload-media'){const file=$('#media-file')?.files?.[0];if(!file)return toast('Choose an image.');if(file.size>2_000_000||!['image/png','image/jpeg','image/webp'].includes(file.type))return toast('Use PNG, JPEG or WebP under 2 MB.');const reader=new FileReader();reader.onload=async()=>{const result=await action('/api/media','POST',{data:reader.result});if(result)toast('Image added to preview.');};reader.readAsDataURL(file);return;}
  if(target.closest('.ad-preview'))toast('Illustrative ad preview only.');
});
async function startRecording(){voiceError='';if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){voiceError='Recording is unavailable on this device. Use text entry.';render();return;}
  try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});recordedChunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)recordedChunks.push(e.data);};recorder.onstop=async()=>{stream.getTracks().forEach(x=>x.stop());clearTimeout(recordTimer);const blob=new Blob(recordedChunks,{type:recorder.mimeType||'audio/webm'});recorder=null;render();if(!blob.size)return;const form=new FormData();form.set('audio',blob,'recording.webm');form.set('language',locale());try{const result=await api('/api/audio/transcribe','POST',form);transcript=result.transcript;toast('Transcript ready. Edit it before sending.');render();}catch(e){voiceError=`${e.message} Use text instead.`;render();}};recorder.start();recordTimer=setTimeout(()=>stopRecording(),60000);render();}catch(e){voiceError='Microphone unavailable or permission denied. Use text entry.';render();}}
function stopRecording(){if(recorder?.state==='recording')recorder.stop();}
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next&&next!==page){page=next;render();}});
try{setState(await api('/api/state'));}catch{document.querySelector('#main').innerHTML='<div class="alert danger">Could not load the app. Refresh to retry.</div>';}
